QImage pixels(std::shared_ptr<GpuResources> gpu,const RecordedFrame& frame){
    require(bool(frame.texture),"owned composed frame available");D3D11_TEXTURE2D_DESC d{};frame.texture->GetDesc(&d);d.Usage=D3D11_USAGE_STAGING;d.CPUAccessFlags=D3D11_CPU_ACCESS_READ;d.BindFlags=d.MiscFlags=0;ComPtr<ID3D11Texture2D> readback;
    winrt::check_hresult(gpu->device->CreateTexture2D(&d,nullptr,&readback));std::lock_guard lock(*gpu->contextMutex);gpu->context->CopyResource(readback.Get(),frame.texture.Get());D3D11_MAPPED_SUBRESOURCE map{};winrt::check_hresult(gpu->context->Map(readback.Get(),0,D3D11_MAP_READ,0,&map));QImage image(int(d.Width),int(d.Height),QImage::Format_ARGB32);for(UINT y=0;y<d.Height;++y)memcpy(image.scanLine(int(y)),static_cast<const char*>(map.pData)+y*map.RowPitch,d.Width*4);gpu->context->Unmap(readback.Get(),0);return image;
}
void settle(Runtime& runtime,uint64_t prior=0){for(int i=0;i<200;++i){if(runtime.status().frames>prior+3)return;std::this_thread::sleep_for(std::chrono::milliseconds(10));}throw std::runtime_error(runtime.status().error.toStdString());}
bool blue(QRgb p){return qBlue(p)>180&&qRed(p)<50;}
bool red(QRgb p){return qRed(p)>170&&qBlue(p)<60;}
class FixtureAudio final:public SceneAudioProvider{
    size_t count_;
public:
    std::atomic_uint starts{};
    explicit FixtureAudio(size_t count=3):count_(count){}
    std::vector<bool> microphoneStems()const override{std::vector<bool> result(count_);for(size_t n=0;n<count_;++n)result[n]=n%2==1;return result;}
    std::vector<std::wstring> stems()const override{std::vector<std::wstring> result;for(size_t n=0;n<count_;++n)result.push_back(n==0?L"Fixture Application":n==1?L"Fixture Microphone":n==2?L"Fixture Desktop":L"Named source "+std::to_wstring(n));return result;}
    bool start(std::shared_ptr<RecordingIngress>,std::wstring&)override{++starts;return true;}
    void origin(std::chrono::steady_clock::time_point)override{}
    int advanceMilliseconds()const override{return 0;}
    void stop()override{}
    void render(uint64_t first,uint64_t frames,std::vector<int16_t>& mix,std::vector<std::vector<int16_t>>& stems)override{
        stems.assign(count_,std::vector<int16_t>(frames*2));mix.assign(frames*2,0);for(uint64_t i=0;i<frames;++i)for(size_t n=0;n<count_;++n){auto sample=int16_t(1800*std::sin((first+i)*2*3.141592653589793*(300+n*150)/48000));stems[n][i*2]=stems[n][i*2+1]=sample;mix[i*2]+=sample;mix[i*2+1]+=sample;}
    }
};
